<script setup>
import CampusLayout from '../../Layouts/MarketplaceLayout.vue';
import { Link, useForm } from '@inertiajs/vue3';
const props = defineProps({ businesses: Object, managedBusinesses: Array, isAdmin: Boolean });
const form = useForm({ name:'', type:'student', description:'' });
const statusForm = useForm({ status:'suspended', reason:'Cambio administrativo de estado' });
const config = useForm({ name:'', type:'student', description:'', visibility:'public', payment_methods:['wallet'], tags:[], contact:{email:'',phone:''}, policies:{returns:'',privacy:''}, hours:{}, hours_json:'{}', delivery_points:[], delivery_points_text:'', spei_instructions:'', openpay_profile_id:'' });
const storefront = useForm({ name:'', brand:'', description:'', logo:'', banner:'', policies:{returns:'',privacy:''}, hours:{}, hours_json:'{}', delivery_points:[], delivery_points_text:'', channels:['email'], published:false });
function loadStore(b) { const s=b.storefront || {}; storefront.name=s.name || b.name; storefront.brand=s.brand || b.name; storefront.description=s.description || b.description || ''; storefront.logo=s.logo || ''; storefront.banner=s.banner || ''; storefront.policies=s.policies || {returns:'',privacy:''}; storefront.hours=s.hours || {}; storefront.hours_json=JSON.stringify(s.hours || {},null,2); storefront.delivery_points=s.delivery_points || []; storefront.delivery_points_text=(s.delivery_points || []).join(', '); storefront.channels=s.channels || ['email']; storefront.published=!!s.published; }
function loadConfig(b) { config.name=b.name; config.type=b.type; config.description=b.description || ''; config.visibility=b.visibility || 'private'; config.payment_methods=b.payment_methods || ['wallet']; config.tags=b.tags || []; config.contact=b.contact || {email:'',phone:''}; config.policies=b.policies || {returns:'',privacy:''}; config.hours=b.hours || {}; config.hours_json=JSON.stringify(b.hours || {},null,2); config.delivery_points=b.delivery_points || []; config.delivery_points_text=(b.delivery_points || []).join(', '); config.spei_instructions=b.spei_instructions || ''; config.openpay_profile_id=b.openpay_profile_id || ''; }
function saveStore(b) { if (!storefront.name) storefront.name = b.name; if (!storefront.brand) storefront.brand = b.name; if (!storefront.description) storefront.description = b.description || ''; let hours; try { hours=JSON.parse(storefront.hours_json || '{}'); } catch { alert('Los horarios deben ser un objeto JSON.'); return; } storefront.transform(data=>({...data,hours,delivery_points:(data.delivery_points_text || '').split(',').map(x=>x.trim()).filter(Boolean)})).put(`/tienda/negocios/${b.id}/tienda`, { preserveScroll:true }); }
function saveConfig(b) { config.name = b.name; config.type = b.type; config.description = b.description || ''; let hours; try { hours=JSON.parse(config.hours_json || '{}'); } catch { alert('Los horarios deben ser un objeto JSON.'); return; } config.transform(data=>({...data,hours,delivery_points:(data.delivery_points_text || '').split(',').map(x=>x.trim()).filter(Boolean)})).put(`/tienda/negocios/${b.id}`, { preserveScroll:true }); }
function changeStatus(b,status) { statusForm.status=status; statusForm.post(`/tienda/negocios/${b.id}/estado`, {preserveScroll:true}); }
</script>
<template>
  <CampusLayout title="Negocios">
    <div class="max-w-[1180px] mx-auto space-y-5">
      <div class="flex justify-between items-end"><div><div class="text-xs text-campus-blue font-semibold">3.1 · 3.2 · 3.3</div><h1 class="text-2xl font-bold text-slate-800">Negocios virtuales</h1><p class="text-sm text-slate-500 mt-1">Registro, autorización, tienda y personal.</p></div><Link href="/tienda/solicitudes" class="rounded-lg bg-campus-blue text-white px-4 py-2 text-sm">Solicitudes y autorización</Link></div>
      <Link href="/tienda/solicitudes" class="block rounded-lg border bg-white p-4 text-sm text-campus-blue">Registrar un negocio o solicitar una tienda para mi organización →</Link>
      <div class="grid md:grid-cols-2 xl:grid-cols-3 gap-4">
        <div v-for="b in businesses.data" :key="b.id" class="bg-white border border-campus-border rounded-xl p-5 shadow-card">
          <div class="flex justify-between gap-2"><div class="h-11 w-11 rounded-lg bg-blue-50 text-campus-blue flex items-center justify-center font-bold">CD</div><span class="text-[10px] px-2 py-1 rounded-full h-fit" :class="b.status==='approved' ? 'bg-green-50 text-green-700':'bg-amber-50 text-amber-700'">{{ b.status }}</span></div>
          <h3 class="font-bold text-slate-800 mt-4">{{ b.name }}</h3><p class="text-xs text-slate-500 mt-1">{{ b.description }}</p><div class="mt-3 text-xs text-slate-500">Tipo: <b>{{ b.type }}</b> · Visibilidad: <b>{{ b.visibility }}</b></div>
          <div v-if="isAdmin" class="mt-3 flex flex-wrap gap-2"><button v-if="b.status!=='approved'" @click="changeStatus(b,'approved')" class="rounded bg-green-700 text-white px-2 py-1 text-xs">Autorizar</button><button v-if="b.status==='approved'" @click="changeStatus(b,'suspended')" class="rounded bg-red-600 text-white px-2 py-1 text-xs">Suspender</button><button v-if="b.status==='suspended'" @click="changeStatus(b,'retired')" class="rounded border px-2 py-1 text-xs">Dar de baja</button></div>
          <div v-if="managedBusinesses?.some(x=>x.id===b.id) || isAdmin" class="mt-4 border-t pt-4 space-y-3">
            <div v-if="b.can_configure"><h4 class="text-sm font-bold">Configuración comercial</h4><button @click="loadConfig(b)" class="rounded border px-3 py-2 text-xs">Cargar ajustes actuales</button><label class="block text-xs text-slate-600">Visibilidad</label><select v-model="config.visibility" class="w-full rounded border p-2 text-xs"><option value="public">Público</option><option value="private">Privado</option></select><input v-model="config.contact.email" type="email" placeholder="Correo de contacto" class="w-full rounded border p-2 text-xs"/><input v-model="config.contact.phone" placeholder="Teléfono de contacto" class="w-full rounded border p-2 text-xs"/><textarea v-model="config.spei_instructions" placeholder="Instrucciones SPEI públicas para compradores (sin datos secretos)" class="w-full rounded border p-2 text-xs"></textarea><input v-model="config.openpay_profile_id" placeholder="Identificador público del perfil Openpay (sin llaves)" class="w-full rounded border p-2 text-xs"/><input v-model="config.policies.returns" placeholder="Política de devoluciones" class="w-full rounded border p-2 text-xs"/><input v-model="config.policies.privacy" placeholder="Política de privacidad" class="w-full rounded border p-2 text-xs"/><input v-model="config.delivery_points_text" placeholder="Puntos de entrega separados por coma" class="w-full rounded border p-2 text-xs"/><textarea v-model="config.hours_json" rows="2" placeholder='Horarios JSON, ej. {"lun-vie":"08:00-18:00"}' class="w-full rounded border p-2 text-xs font-mono"></textarea><div class="text-xs text-slate-600">Métodos de pago aceptados</div><div class="grid grid-cols-2 gap-2 text-xs"><label v-for="method in ['wallet','bonus','points','mixed','spei','openpay']" :key="method"><input type="checkbox" :value="method" v-model="config.payment_methods"/> {{ method.toUpperCase() }}</label></div><button @click="saveConfig(b)" class="rounded border px-3 py-2 text-xs">Guardar configuración</button>
            </div><h4 class="text-sm font-bold">Publicación de tienda</h4><button @click="loadStore(b)" class="rounded border px-3 py-2 text-xs">Cargar tienda actual</button><input v-model="storefront.name" :placeholder="b.name" class="w-full rounded border p-2 text-xs"/><input v-model="storefront.brand" placeholder="Marca" class="w-full rounded border p-2 text-xs"/><textarea v-model="storefront.description" placeholder="Descripción de la tienda" class="w-full rounded border p-2 text-xs"></textarea><input v-model="storefront.logo" placeholder="URL de logo" class="w-full rounded border p-2 text-xs"/><input v-model="storefront.banner" placeholder="URL de portada" class="w-full rounded border p-2 text-xs"/><input v-model="storefront.policies.returns" placeholder="Política de devoluciones" class="w-full rounded border p-2 text-xs"/><input v-model="storefront.policies.privacy" placeholder="Política de privacidad" class="w-full rounded border p-2 text-xs"/><input v-model="storefront.delivery_points_text" placeholder="Puntos de entrega separados por coma" class="w-full rounded border p-2 text-xs"/><textarea v-model="storefront.hours_json" rows="2" placeholder="Horarios JSON" class="w-full rounded border p-2 text-xs font-mono"></textarea><label class="flex gap-2 text-xs"><input type="checkbox" v-model="storefront.published"/> Publicar tienda (solo negocio aprobado)</label><button @click="saveStore(b)" class="rounded bg-campus-blue text-white px-3 py-2 text-xs">Guardar tienda</button>
            <p class="text-xs text-slate-500">El personal y sus permisos se administran en Identidad. La API de cambios de integrantes queda pendiente de integración.</p>
          </div>
        </div>
      </div>
      <div v-if="!businesses.data?.length" class="bg-white p-10 rounded-xl text-center text-slate-400">No hay negocios visibles.</div>
    </div>
  </CampusLayout>
</template>
